        const electronProxy={...electron,clipboard:fixtureClipboard,desktopCapturer:{...electron.desktopCapturer,getSources:async()=>{sourceEnumerations++;if(!holdNextSourceEnumeration)return[];holdNextSourceEnumeration=false;return new Promise(resolve=>{releaseSourceEnumeration=()=>{releaseSourceEnumeration=null;resolve([{id:'window:stale-workspace-fixture',name:'EverQuest Synthetic Stale Source'}]);};});}},dialog:{...electron.dialog,showSaveDialog:async()=>{if(++saveAttempts===1)throw Error('Fixture disk is temporarily unavailable.');return{canceled:false,filePath:savePath};},showOpenDialog:async()=>{openAttempts++;return{canceled:false,filePaths:[path.join(root,'tests/fixtures/screen-read/item.png')]};}},shell:{...electron.shell,openExternal:async()=>{throw Error('External URLs disabled in capture workspace fixture');}}};
