            const chunks=[];for await(const chunk of req)chunks.push(chunk);const params=req.method==='POST'?new URLSearchParams(Buffer.concat(chunks).toString()):url.searchParams,authenticated=req.headers.cookie?.includes('eozUiLogin=verified');
