        const change=async(selector,value,event='input')=>execute(main,(selector,value,event)=>{const element=document.querySelector(selector);if(!element)throw Error(`Missing UI control: ${selector}`);element.value=value;element.dispatchEvent(new Event(event,{bubbles:true}));},selector,value,event);
